"""SET_C: independent public documentation/event-shape validation traces.

The records are transcribed from public framework contracts and examples, not
generated by running a provider.  They are kept separate from SET_A and SET_B;
the report treats their lack of raw production export as a limitation.
"""

from __future__ import annotations

from typing import Any


def _event(step: int, **kwargs: Any) -> dict[str, Any]:
    value = {"event_type": "event", "step_id": step, "timestamp": float(step)}
    value.update(kwargs)
    return value


def _trace(trace_id: str, framework: str, adapter: str, source: str, label: str, rationale: str, events: list[dict[str, Any]], completeness: str = "complete") -> dict[str, Any]:
    return {"trace_id": trace_id, "framework": framework, "adapter": adapter, "source": source, "raw_trace_reference": source, "workflow_type": "PUBLIC_TRACE", "human_label": label, "label_rationale": rationale, "raw_events": events, "trace_completeness": completeness, "provenance": "independent_public_documentation"}


def public_trace_traces() -> list[dict[str, Any]]:
    langgraph_stream = "https://docs.langchain.com/oss/python/langgraph/streaming"
    langgraph_persist = "https://docs.langchain.com/oss/python/langgraph/persistence"
    langchain_callbacks = "https://docs.langchain.com/oss/python/langchain/observability"
    openai_running = "https://openai.github.io/openai-agents-python/running_agents/"
    openai_trace = "https://openai.github.io/openai-agents-python/tracing/"
    pydantic_agents = "https://ai.pydantic.dev/agents/"
    pydantic_graph = "https://ai.pydantic.dev/graph/beta/"
    autogen_terms = "https://microsoft.github.io/autogen/stable/user-guide/agentchat-user-guide/tutorial/termination.html"
    autogen_messages = "https://microsoft.github.io/autogen/dev/user-guide/agentchat-user-guide/tutorial/messages.html"
    restate_journal = "https://docs.restate.dev/foundations/key-concepts"
    temporal_retry = "https://docs.temporal.io/encyclopedia/retry-policies"
    dbos_ai = "https://docs.dbos.dev/ai/ai-quickstart"
    traces: list[dict[str, Any]] = []

    # Public checkpoint/state examples: two stagnating, two progressing, one ambiguous.
    traces.append(_trace("C01", "LangGraph", "langgraph-compat", langgraph_stream, "STAGNATING", "The documented checkpoint stream repeats the same checkpoint/state after a permanent node error.", [{"event": "checkpoints", "name": "node", "step": i, "data": {"output": {"status": "error"}, "state_after": {"phase": "node"}, "error": {"type": "NodeError", "message": "invalid input"}}, "metadata": {"checkpoint_id": "cp-0", "langgraph_step": i}} for i in range(1, 5)]))
    traces.append(_trace("C02", "LangGraph", "langgraph-compat", langgraph_persist, "PROGRESSING", "The persistence example advances state and checkpoint/artifact identity at each graph step.", [{"event": "checkpoints", "name": "write", "step": i, "data": {"output": {"ok": True}, "state_before": {"files": i - 1}, "state_after": {"files": i}, "artifacts_created": [f"patch-{i}"]}, "metadata": {"checkpoint_id": f"cp-{i}", "langgraph_step": i}} for i in range(1, 5)]))
    traces.append(_trace("C03", "LangGraph", "langgraph-compat", langgraph_stream, "LOOPING", "A public recursion-limit shape alternates two nodes while the durable state version remains unchanged.", [{"event": "tasks", "name": "node_a" if i % 2 else "node_b", "step": i, "data": {"output": {"phase": "A" if i % 2 else "B"}, "state_after": {"state_version": "v0"}, "error": {"type": "GraphRecursion", "message": "recursion limit"}}, "metadata": {"state_version": "v0", "langgraph_step": i}} for i in range(1, 7)]))
    traces.append(_trace("C04", "LangGraph", "langgraph-compat", langgraph_persist, "STAGNATING", "Repeated execution timeout plus a stable checkpoint supports execution stagnation, while the remote side effect remains unknown.", [{"event": "tasks", "name": "external", "step": i, "data": {"output": {"status": "timeout"}, "checkpoint_id": "cp-external-0"}, "metadata": {}} for i in range(1, 5)], "partial"))

    # LangChain callback/observability shapes.
    traces.append(_trace("C05", "LangChain", "langchain-compat", langchain_callbacks, "STAGNATING", "Callback events show a repeated permanent error and a stable declared state version.", [_event(i, event="on_chain_error", name="retrieve", output=None, error_type="HTTPError", error_message="400 invalid", state_after={"phase": "retrieve"}, metadata={"state_version": "retrieve-0"}) for i in range(1, 5)]))
    traces.append(_trace("C06", "LangChain", "langchain-compat", langchain_callbacks, "PROGRESSING", "Callback results expose a new document artifact and advancing state.", [_event(i, event="on_chain_end", name="retrieve", output={"document_id": i}, state_before={"documents": i - 1}, state_after={"documents": i}, artifacts_created=[f"doc-{i}"]) for i in range(1, 5)]))
    traces.append(_trace("C07", "LangChain", "langchain-compat", langchain_callbacks, "STAGNATING", "A stable state version and repeated error family expose no progress despite callback retries.", [_event(i, event="on_chain_error", name="parse", output=None, error_type="ValidationError", error_message="invalid schema", state_after={"phase": "parse"}, metadata={"state_version": "parse-0"}) for i in range(1, 5)]))
    traces.append(_trace("C08", "LangChain", "langchain-compat", langchain_callbacks, "STAGNATING", "A repeated validation failure has no framework-native anchor, but the developer supplied a stable checkpoint key explicitly.", [_event(i, event="on_chain_error", name="parse", output=None, error_type="ValidationError", error_message="invalid schema", metadata={"developer_checkpoint": "parse-0"}) for i in range(1, 5)]))

    # OpenAI Agents trace/run shapes: trace/span IDs are deliberately not progress anchors.
    traces.append(_trace("C09", "OpenAI Agents", "openai-agents", openai_running, "STAGNATING", "Function tool failures repeat with a stable explicit state version in run metadata.", [_event(i, type="function_error", tool="save", result=None, error_type="TimeoutError", error_message="upstream timeout", state_after={"phase": "save"}, metadata={"state_version": "save-0", "trace_id": "trace_same"}) for i in range(1, 5)]))
    traces.append(_trace("C10", "OpenAI Agents", "openai-agents", openai_trace, "PROGRESSING", "Function span output records a verified artifact and changed state.", [_event(1, type="function_span", tool="lookup", result={"id": 1}, state_after={"phase": "lookup"}, metadata={"span_id": "s1"}), _event(2, type="function_span", tool="save", result={"ok": True}, state_before={"phase": "lookup"}, state_after={"phase": "saved"}, metadata={"artifact_id": "record-1", "span_id": "s2"})]))
    traces.append(_trace("C11", "OpenAI Agents", "openai-agents", openai_trace, "UNKNOWN", "Changing trace/span IDs prove execution activity, not task progress.", [_event(i, type="generation", tool="agent", result={"text": "same plan"}, metadata={"trace_id": f"t{i}", "span_id": f"s{i}"}) for i in range(1, 5)], "sparse"))
    traces.append(_trace("C12", "OpenAI Agents", "openai-agents", openai_running, "STAGNATING", "A repeated tool protocol error is accompanied by a stable externally supplied checkpoint.", [_event(i, type="function_error", tool="lookup", result=None, error_type="ProtocolError", error_message="tool output missing", state_after={"phase": "lookup"}, metadata={"checkpoint_id": "cp-lookup"}) for i in range(1, 5)]))

    # PydanticAI event/graph shapes.
    traces.append(_trace("C13", "PydanticAI", "pydantic-ai", pydantic_agents, "STAGNATING", "Retries repeat a validation error with a stable state version exposed by the run context.", [_event(i, kind="model_retry", tool="validate", result=None, error_type="ValidationError", error_message="invalid output", state_after={"phase": "validate"}, metadata={"state_version": "validate-0"}) for i in range(1, 5)]))
    traces.append(_trace("C14", "PydanticAI", "pydantic-ai", pydantic_graph, "PROGRESSING", "Graph nodes produce structured outputs and advance state between steps.", [_event(1, kind="node_end", tool="get_number", result={"value": 15}, state_before={"phase": "start"}, state_after={"phase": "number"}), _event(2, kind="node_end", tool="is_positive", result={"positive": True}, state_before={"phase": "number"}, state_after={"phase": "done"}, artifacts_created=["decision"])]))
    traces.append(_trace("C15", "PydanticAI", "pydantic-ai", pydantic_agents, "UNKNOWN", "Model retry text varies but the caller's intended recovery and external state are absent.", [_event(i, kind="model_retry", tool="validate", result={"message": f"variant {i}"}, error_type="ModelRetry") for i in range(1, 5)], "sparse"))
    traces.append(_trace("C16", "PydanticAI", "pydantic-ai", pydantic_agents, "STAGNATING", "The same structured output failure repeats while an explicit checkpoint remains fixed.", [_event(i, kind="tool_error", tool="output", result=None, error_type="SchemaError", error_message="missing field", state_after={"phase": "output"}, metadata={"checkpoint_id": "output-0"}) for i in range(1, 5)]))

    # AutoGen message/termination shapes.
    traces.append(_trace("C17", "AutoGen", "autogen", autogen_terms, "STAGNATING", "Messages repeat a policy failure while the workflow exposes a stable state version.", [_event(i, kind="ToolCallExecutionEvent", tool="approve", output=None, error_type="PolicyError", error_message="approval unavailable", state_after={"phase": "approve"}, metadata={"state_version": "approve-0"}) for i in range(1, 5)]))
    traces.append(_trace("C18", "AutoGen", "autogen", autogen_messages, "PROGRESSING", "Tool execution, handoff, and termination produce a new resource and advancing state.", [_event(1, kind="ToolCallExecutionEvent", tool="lookup", output={"id": 1}, state_before={"phase": "lookup"}, state_after={"phase": "handoff"}), _event(2, kind="TextMessage", tool="writer", output={"draft": True}, state_before={"phase": "handoff"}, state_after={"phase": "draft"}, artifacts_created=["draft"]), _event(3, kind="StopMessage", tool="reviewer", output={"approved": True}, state_before={"phase": "draft"}, state_after={"phase": "done"})]))
    traces.append(_trace("C19", "AutoGen", "autogen", autogen_terms, "UNKNOWN", "Message IDs and timestamps change, but no trusted state or verified outcome exists.", [_event(i, kind="TextMessage", tool="agent", output={"text": "same plan"}, metadata={"message_id": f"m{i}", "timestamp": i}) for i in range(1, 5)], "sparse"))
    traces.append(_trace("C20", "AutoGen", "autogen", autogen_terms, "STAGNATING", "The documented termination condition is never reached; repeated errors share a stable checkpoint.", [_event(i, kind="ToolCallExecutionEvent", tool="finish", output=None, error_type="TerminationError", error_message="condition not reached", state_after={"phase": "finish"}, metadata={"checkpoint_id": "finish-0"}) for i in range(1, 5)]))
    return traces
